def on_if(node)
  return if accepted_form?(node)
  return if use_variable_assignment_in_condition?(node)

  if (guard_clause = node.if_branch&.guard_clause?)

private

def use_variable_assignment_in_condition?(node)
  assigned_variables = node.condition.each_node(:lvasgn).map { |n| n.children.first }
  return false if assigned_variables.empty?

  node.branches.any? do |branch|
    branch.each_node(:lvar).any? { |lvar| assigned_variables.include?(lvar.children.first) }
  end
end

